 document.getElementById('v2gAddProfile').onclick=()=>{const n=(els.profileName.value||'').trim();if(!n){status('Enter a name for this input profile first.',true);return;}data.profiles[n]=data.profiles[n]||{notes:{}};data.activeProfile=n;els.profileName.value='';saveData();renderProfiles();renderCalibration();status('Profile ready: '+n);};
 els.mic.onclick=()=>listening?stopMic():startMic();
