async function refreshAudioInputs(afterPermission){if(!els.device||!navigator.mediaDevices?.enumerateDevices)return;const previous=selectedDeviceId||els.device.value||'';try{const inputs=(await navigator.mediaDevices.enumerateDevices()).filter(d=>d.kind==='audioinput');els.device.innerHTML='<option value="">System default microphone</option>'+inputs.map((d,i)=>'<option value="'+escapeHtml(d.deviceId)+'">'+escapeHtml(d.label||('Microphone '+(i+1)))+'</option>').join('');if(previous&&inputs.some(d=>d.deviceId===previous))els.device.value=previous;else if(!afterPermission)els.device.value='';selectedDeviceId=els.device.value||'';if(els.deviceStatus)els.deviceStatus.textContent=inputs.length?inputs.length+' input device'+(inputs.length===1?'':'s')+' found':'No inputs listed; system default may still work';}catch(e){if(els.deviceStatus)els.deviceStatus.textContent='Input list unavailable';}}
function meterPercent(rms){const db=20*Math.log10(Math.max(1e-6,+rms||0));return Math.max(0,Math.min(100,(db+60)/60*100));}
function updateInputMeter(rms,buf){if(!els.levelFill||!els.levelText)return;const db=20*Math.log10(Math.max(1e-6,+rms||0));let peak=0;if(buf)for(let i=0;i<buf.length;i++)if(Math.abs(buf[i])>peak)peak=Math.abs(buf[i]);els.levelFill.style.width=meterPercent(rms).toFixed(1)+'%';els.levelFill.style.background=(peak>.95||db>-6)?'#ef4444':db>-18?'#f59e0b':'#34d399';els.levelText.textContent=(db<-58?'Very quiet · ':db>-6?'Too loud · ':'Input · ')+db.toFixed(0)+' dBFS'+(peak>.95?' · clipping risk':'');}
function appReferenceA(){const el=document.getElementById('tuneVal');const v=el?Number(el.value):440;return Number.isFinite(v)&&v>=390&&v<=490?v:440;}
function tunerReading(hz,aRef=appReferenceA()){const midi=69+12*Math.log2(hz/aRef),nearest=Math.round(midi);return {midi:nearest,cents:(midi-nearest)*100};}
