  if(activeVoice&&Math.abs(stepCents)>22&&!attack&&!popHit){continuousBendActive=true;}if(activeVoice&&Math.abs(centsOff(p.hz,activeMidi==null?nearest:activeMidi))<28)continuousBendActive=false;
