function applyCurrentBend(hz){if(!activeVoice||!activeBaseHz||!(hz>0))return;const range=+data.bendRange||2.5;const semis=12*Math.log2(hz/activeBaseHz);const bend=bendSemitonesForVoice(semis,range);try{activeVoice.bend(bend);}catch(_){}}
